import pRetry, {AbortError} from 'p-retry';

const body = await pRetry(async () => {
  const res = await fetch(url, {signal});
  if (res.status === 404) throw new AbortError('permanent');
  if (!res.ok) throw new Error(`transient ${res.status}`);
  return res.json();
}, {retries: 5, factor: 2, minTimeout: 200, maxTimeout: 30_000, randomize: true, signal});

import {DynamoDBClient} from '@aws-sdk/client-dynamodb';

const client = new DynamoDBClient({
  maxAttempts: 5,   // standard retry mode is the default: full jitter + retry quota
});
await client.send(new GetItemCommand({TableName: table, Key: key}));

